use host;
fn main() {
    status := host::write_file(view("w.txt"), view("windows-io"));
    assert(status == 0);
    contents := host::read_file(view("w.txt"));
    host::print(view(contents));
    println(contents.len());
}

struct Point {
    x: u64,
    y: u64,
}
fn main() -> u64 {
    p := Point { x: 3, y: 4 };
    return p.x + p.y;
}

use host;
fn main() {
    println(host::argc() - 1);
    mut i = 1;
    while i < host::argc() {
        host::print(host::arg(i));
        println();
        i += 1;
    }
}
